use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const MAX_ROUNDS: usize = 4;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_system(intent: Intent) -> String {
    format!(
        "You are a customer-support assistant. The customer's intent is '{}'. \
         Answer only from the supplied knowledge. If you need more, request the \
         'lookup' tool with a focused query.",
        intent_label(intent)
    )
}

fn build_prompt(ctx: &ConversationContext, extra: &[String]) -> String {
    let mut out = String::new();
    out.push_str("Question:\n");
    out.push_str(&ctx.question);
    out.push('\n');

    if !ctx.knowledge.is_empty() {
        out.push_str("\nKnowledge:\n");
        for k in &ctx.knowledge {
            out.push_str("- ");
            out.push_str(k);
            out.push('\n');
        }
    }

    if !extra.is_empty() {
        out.push_str("\nAdditional lookup results:\n");
        for k in extra {
            out.push_str("- ");
            out.push_str(k);
            out.push('\n');
        }
    }

    out
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = build_system(ctx.intent);
        let mut extra: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &extra);
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        if results.is_empty() {
                            extra.push(format!(
                                "(no knowledge-base results for '{}')",
                                req.query
                            ));
                        } else {
                            extra.extend(results);
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "model requested unavailable tool '{}'",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge to an answer".to_string(),
        })
    }
}

export!(Node);
```

If the enrichment lookup is genuinely a wanted feature, the right path is to update the graph type to grant `http-client`, have the node *use* the fetched record in its output, and send only to an endpoint that's meant to receive user questions — happy to help build that version.

